function mdY(d){if(!d)return'';let m=String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?Number(m[2])+'/'+Number(m[3])+'/'+m[1]:d}function fmtTime(t){if(!t)return'';const m=String(t).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(t);let h=Number(m[1]);const ap=h>=12?'PM':'AM';h=h%12||12;return h+':'+m[2]+' '+ap}async function refreshFollowedSchedules(){if(!shows.length)return;let changed=false;const today=new Date(),todayKey=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');const fresh=await Promise.all(shows.map(async s=>{try{const [x,eps]=await Promise.all([fetch('https://api.tvmaze.com/shows/'+Number(s.id)+'?embed=nextepisode',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('https://api.tvmaze.com/shows/'+Number(s.id)+'/episodes',{cache:'no-store'}).then(r=>r.ok?r.json():[]).catch(()=>[])]);const e=x._embedded?.nextepisode||{};rememberEpisodes(s.id,eps);const todays=(Array.isArray(eps)?eps:[]).filter(ep=>ep.airdate===todayKey);const current=todays.length?todays[0]:null;const keepToday=s.airdate===todayKey&&e.airdate!==todayKey;const n=applyVerifiedSchedule({...s,network:x.network?.name||x.webChannel?.name||s.network||'',webChannel:!!x.webChannel,status:x.status||s.status||'',airdate:current?todayKey:(keepToday?s.airdate:(e.airdate||s.airdate||'')),airtime:current?(current.airtime||s.airtime||''):(keepToday?s.airtime:(e.airtime||s.airtime||'')),airstamp:current?(current.airstamp||s.airstamp||''):(keepToday?s.airstamp:(e.airstamp||s.airstamp||'')),next_episode:current?(todays.length>1?todays.length+' episodes today':(current.name||s.next_episode||'')):(keepToday?s.next_episode:(e.name||s.next_episode||''))});if(JSON.stringify(n)!==JSON.stringify(s))changed=true;return n}catch{return s}}));if(changed){shows=fresh;save(K.shows,shows);syncNotificationTitles();if(route==='home')home();else if(route==='calendar')calendar();else if(route==='shows')myshows()}}
const EPISODE_HISTORY_KEY='mytv-v6-episode-history';let episodeHistory=load(EPISODE_HISTORY_KEY,{});function rememberEpisodes(id,eps){if(!Array.isArray(eps))return;const key=String(id);const prior=episodeHistory[key]||[];const map=new Map(prior.map(e=>[String(e.id||e.airdate+'|'+e.name),e]));eps.forEach(e=>{if(e.airdate){const entry={id:e.id,airdate:e.airdate,airtime:e.airtime||'',name:e.name||''};map.set(String(e.id||e.airdate+'|'+e.name),entry)}});episodeHistory[key]=Array.from(map.values()).sort((a,b)=>a.airdate.localeCompare(b.airdate));save(EPISODE_HISTORY_KEY,episodeHistory)}
const STREAM_RELEASE_TIMES={'Netflix':'03:00','Disney+':'03:00','HBO Max':'03:00','Max':'03:00','Paramount+':'03:00','AMC+':'03:00','ALLBLK':'03:00','BET+':'03:00','Hulu':'00:00','Apple TV+':'00:00','Peacock':'03:00'};
