function normalizeBroadcastTime(t){if(!t)return'';const m=String(t).match(/^(\d{1,2}):(\d{2})/);if(!m)return String(t);let h=Number(m[1]),min=Number(m[2]);if(min>=1&&min<=7)min=0;else if(min>=28&&min<=37)min=30;else if(min>=53&&min<=59){h=(h+1)%24;min=0}return String(h).padStart(2,'0')+':'+String(min).padStart(2,'0')}
