function countdownText(x){const t=showStart(x);if(!Number.isFinite(t)||t>9e15)return'';const n=Date.now(),d=t-n;if(d<=0)return dayDiff(x.airdate)===0?'Airing today':'';const mins=Math.floor(d/60000);if(mins<60)return'Starts in '+Math.max(1,mins)+'m';const hrs=Math.floor(mins/60);if(hrs<24)return'Starts in '+hrs+'h '+(mins%60)+'m';const days=Math.floor(hrs/24);return'Starts in '+days+'d '+(hrs%24)+'h'}function favoriteMark(x){return favorites[String(x.id)]?' ★':''}function toggleFavorite(id){const k=String(id);if(favorites[k])delete favorites[k];else favorites[k]=true;save('mytv-v6-favorites',favorites);if(route==='shows')myshows();else home()}function scheduleLine(x){const a=[];if(x?.airdate)a.push(mdY(x.airdate));const t=verifiedTime(x);if(t)a.push(t);else if(x?.airdate)a.push('Time Pending');return a.join(' • ')||'Schedule pending'}function dayDiff(d){if(!d)return null;const a=new Date();a.setHours(0,0,0,0);const b=new Date(d+'T00:00:00');return Math.round((b-a)/86400000)}function label(d){let n=dayDiff(d);if(n===null)return'Upcoming';if(n<0)return'Aired';if(n===0)return'Tonight';return new Date(d+'T00:00:00').toLocaleDateString('en-US',{weekday:'long'})}
