function movieReleaseCountdown(d){if(!d)return'Release date pending';const today=new Date();today.setHours(0,0,0,0);const release=new Date(d+'T00:00:00');const days=Math.ceil((release-today)/86400000);if(days>1)return'⏳ '+days+' days until release';if(days===1)return'⏳ Releases tomorrow';if(days===0)return'🎬 Releases today';return'✓ Released'}
function movieWatchlistView(){if(!movieWatchlist.length)return '<div class="empty movie-watchlist-empty">No movies saved yet. Add movies from Discover → Movies.</div>';return '<div class="movie-grid watchlist-grid">'+movieWatchlist.map(x=>'<div class="movie-card">'+(x.poster?'<img src="'+esc(x.poster)+'" alt="">':'<div class="movie-no-poster">🎬</div>')+'<div class="movie-card-info"><b>'+esc(x.title)+'</b><span>'+(x.release_date&&x.release_date>=new Date().toISOString().slice(0,10)?'🎟️ In Theaters — '+esc(new Date(x.release_date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})):esc(x.release_date?new Date(x.release_date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Release date pending'))+'</span><span class="movie-countdown">'+esc(movieReleaseCountdown(x.release_date))+'</span><button class="btn" onclick="watchlistMovieDetails('+Number(x.id)+')">Details & Where to Watch</button><button class="movie-remove" onclick="removeMovieWatchlist('+Number(x.id)+')">Remove</button></div></div>').join('')+'</div>'}
function removeMovieWatchlist(id){movieWatchlist=movieWatchlist.filter(x=>Number(x.id)!==Number(id));save('mytv-v6-movie-watchlist',movieWatchlist);showMyShowsTab('movies')}
async function watchlistMovieDetails(id){const x=movieWatchlist.find(m=>Number(m.id)===Number(id));V.innerHTML='<h2>'+esc(x?.title||'Movie Details')+'</h2><button class="btn" onclick="showMyShowsTab(\'movies\')">← Movie Watchlist</button><div id="watchlist-movie-detail" style="margin-top:12px"><div class="sub">Loading details…</div></div>';const R=$('#watchlist-movie-detail');try{const r=await fetch(SUPABASE_URL+'/functions/v1/tmdb-search?id='+id+'&type=movie',{headers:{apikey:SUPABASE_ANON,Authorization:'Bearer '+SUPABASE_ANON}}),d=await r.json(),m=d.detail;if(!m)throw Error();const upcoming=m.release_date&&m.release_date>=new Date().toISOString().slice(0,10);R.innerHTML='<div class="card">'+(m.poster?'<img class="poster" src="'+esc(m.poster)+'">':'')+'<div class="title" style="margin-top:10px">'+esc(m.title)+'</div><div class="sub">'+esc((m.year||'')+' • Movie')+'</div>'+(upcoming?'<div class="theater-badge">🎟️ In Theaters — '+esc(new Date(m.release_date+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}))+'</div>':'')+'<div style="margin-top:10px">'+esc(m.overview||'No description available.')+'</div></div><h3>'+(upcoming?'Theatrical Release':'Where to Watch')+'</h3><div id="watchlist-wtw" class="card"><div class="sub">Checking streaming availability…</div></div>';const W=$('#watchlist-wtw'),p=await realProviders(m.title,'movie',m.id);if(W)W.innerHTML=p?.providers?.length?p.providers.map(a=>'<div class="sub">'+esc(a.name||a.provider_name||'Provider')+'</div>').join(''):'<div class="empty">No verified U.S. streaming options found.</div>'}catch{R.innerHTML='<div class="empty">Movie details are unavailable right now.</div>'}}

async function discover(){V.innerHTML='<div class="discover-head"><h2>Discover</h2><div class="sub">Search for any show or movie.</div></div><div class="discover-search"><input id="q" class="search" placeholder="Search shows and movies" onkeydown="if(event.key===\'Enter\')searchShows()"><button aria-label="Search" onclick="searchShows()">⌕</button></div><button class="movies-browse-btn" onclick="movieDiscover()">🎬 Browse Upcoming Movies</button><div class="discover-title"><b>Discover</b><span>Search above or browse upcoming movies</span></div><div id="results" class="discover-results"><div class="discover-empty">Search for a show, movie, or actor.</div></div>'}

async function movieDiscover(){discoverReturnMode='movies';const R=$('#results');if(!R)return;R.innerHTML='<div class="discover-title"><b>Upcoming Movies</b><span>U.S. releases coming soon</span></div><div class="discover-empty">Loading upcoming movies…</div>';try{const d=await fetch(SUPABASE_URL+'/functions/v1/tmdb-search?mode=upcoming',{headers:{apikey:SUPABASE_ANON,Authorization:'Bearer '+SUPABASE_ANON}}).then(r=>{if(!r.ok)throw Error();return r.json()});const today=new Date().toISOString().slice(0,10),a=(d.results||[]).filter(x=>!x.release_date||x.release_date>=today);R.innerHTML='<div class="discover-title"><b>Upcoming Movies</b><span>U.S. releases coming soon</span></div><div class="movie-grid">'+a.map(x=>{const saved=movieWatchlist.some(y=>Number(y.id)===Number(x.id));return '<div class="movie-card">'+(x.poster?'<img src="'+esc(x.poster)+'" alt="">':'<div class="movie-no-poster">🎬</div>')+'<div class="movie-card-info"><b>'+esc(x.title)+'</b><span>'+esc(x.release_date?new Date(x.release_date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Release date pending')+'</span><button class="btn" '+(saved?'disabled':'onclick="addMovieWatchlist('+Number(x.id)+',\''+encodeURIComponent(x.title)+'\',\''+encodeURIComponent(x.poster||'')+'\',\''+encodeURIComponent(x.release_date||'')+'\')"')+'>'+(saved?'✓ In Watchlist':'Add to Watchlist')+'</button><button class="movie-details" onclick="tmdbDetails('+Number(x.id)+',\'movie\')">Details</button></div></div>'}).join('')+'</div>'}catch{R.innerHTML='<div class="discover-empty">Upcoming movies are unavailable right now.</div>'}}async function addMovieWatchlist(id,title,poster,release_date){if(!(await hasPlan('plus'))){return lockedFeature('Movie Watchlist','Calendar+ or higher')}title=decodeURIComponent(title);poster=decodeURIComponent(poster);release_date=decodeURIComponent(release_date);if(!movieWatchlist.some(x=>Number(x.id)===Number(id))){movieWatchlist.push({id:Number(id),title,poster,release_date});save('mytv-v6-movie-watchlist',movieWatchlist);syncNotificationTitles()}alert('✓ '+title+' added to your movie watchlist.');movieDiscover()}
let discoverReturnMode='search';
function selectDiscoverChip(btn){document.querySelectorAll('.discover-chips button').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active')}function quickDiscover(q,btn){selectDiscoverChip(btn);const e=$('#q');if(e){e.value=q;searchShows()}}let discoverLastQuery='';
async function searchShows(qOverride){
 discoverReturnMode='search';
 const q=(typeof qOverride==='string'?qOverride:($('#q')?.value||'')).trim(),R=$('#results');if(!q||!R)return;discoverLastQuery=q;R.innerHTML='<div class="sub">Searching shows, movies and actors…</div>';
 try{
  const [tm,tv]=await Promise.all([
   fetch(SUPABASE_URL+'/functions/v1/tmdb-search?query='+encodeURIComponent(q),{headers:{apikey:SUPABASE_ANON,Authorization:'Bearer '+SUPABASE_ANON}}).then(r=>r.ok?r.json():({results:[]})),
   fetch('https://api.tvmaze.com/search/shows?q='+encodeURIComponent(q)).then(r=>r.json()).catch(()=>[])
  ]);
  const movie=(tm.results||[]).filter(x=>x.type==='movie').map(x=>'<div class="card discover-pick" onclick="tmdbDetails('+Number(x.id)+',\'movie\')"><div class="showrow">'+(x.poster?'<img class="poster" src="'+esc(x.poster)+'">':'<div></div>')+'<div><div class="title">🎬 '+esc(x.title)+'</div><div class="sub">'+esc((x.actor?'With '+x.actor+' • ':'')+(x.year||'')+' • Movie')+'</div><div class="sub">Movie information only • Tap for details →</div></div></div></div>').join('');
  const show=tv.slice(0,8).map(z=>{const x=z.show,on=shows.some(y=>Number(y.id)===Number(x.id));return '<div class="card"><div class="showrow">'+(x.image?.medium?'<img class="poster" src="'+esc(x.image.medium)+'">':'<div></div>')+'<div><div class="title">📺 '+esc(x.name)+'</div><div class="sub">'+esc(x.network?.name||x.webChannel?.name||x.status||'TV')+'</div></div><div class="actions single">'+(on?'<button class="btn" disabled>Following</button>':'<button class="btn" onclick="follow('+Number(x.id)+')">Save + Follow</button>')+'</div></div></div>'}).join('');
  R.innerHTML=movie+show||'<div class="empty">No results.</div>';
 }catch{R.innerHTML='<div class="empty">Search is unavailable right now.</div>'}
}
function returnToDiscoverResults(){if(discoverReturnMode==='movies'){movieDiscover();return}const q=discoverLastQuery;if(!q){discover();return}const input=$('#q');if(input)input.value=q;searchShows(q)}
async function tmdbDetails(id,type){const R=$('#results');if(!R)return;R.innerHTML='<div class="sub">Loading details…</div>';try{const r=await fetch(SUPABASE_URL+'/functions/v1/tmdb-search?id='+id+'&type='+encodeURIComponent(type),{headers:{apikey:SUPABASE_ANON,Authorization:'Bearer '+SUPABASE_ANON}});const d=await r.json(),x=d.detail;if(!x)throw Error();R.innerHTML='<button class="btn" onclick="returnToDiscoverResults()">← Back to results</button><div class="card" style="margin-top:12px">'+(x.poster?'<img class="poster" src="'+esc(x.poster)+'">':'')+'<div class="title" style="margin-top:10px">'+esc(x.title)+'</div><div class="sub">'+esc((x.year||'')+' • '+(type==='movie'?'Movie':'TV'))+'</div><div style="margin-top:10px">'+esc(x.overview||'No description available.')+'</div></div><h3>Where to Watch</h3><div id="tmdb-wtw" class="card"><div class="sub">Checking streaming availability…</div></div>';const W=$('#tmdb-wtw'),p=await realProviders(x.title,'movie',x.id);if(W)W.innerHTML=p?.providers?.length?p.providers.map(a=>'<div class="sub">'+esc(a.name||a.provider_name||'Provider')+'</div>').join(''):'<div class="empty">No verified U.S. streaming options found.</div>'}catch{R.innerHTML='<div class="empty">Details are unavailable right now.</div>'}}

async function follow(id){try{if(!(await hasPlan('plus'))&&shows.length>=5){lockedFeature('Unlimited Followed Shows','Calendar+ or higher');return}let x=await fetch('https://api.tvmaze.com/shows/'+id+'?embed=nextepisode').then(r=>{if(!r.ok)throw Error();return r.json()});let e=x._embedded?.nextepisode||{};let added=false;if(!shows.some(y=>Number(y.id)===Number(id))){shows.push({id:Number(x.id),name:x.name,network:x.network?.name||x.webChannel?.name||'',webChannel:!!x.webChannel,status:x.status,image:x.image?.medium||'',airdate:e.airdate||'',airtime:e.airtime||'',airstamp:e.airstamp||'',next_episode:e.name||''});save(K.shows,shows);syncNotificationTitles();added=true}alert(added?'✓ '+x.name+' has been added to My Shows.':x.name+' is already in My Shows.');if(route==='discover')await searchShows(discoverLastQuery)}catch{alert('The show could not be added right now. Please try again.')}}
function unfollow(id){shows=shows.filter(x=>Number(x.id)!==Number(id));save(K.shows,shows);syncNotificationTitles();myshows()}
async function details(id){
  let local=shows.find(x=>Number(x.id)===Number(id)),x=local;
  try{x=await fetch('https://api.tvmaze.com/shows/'+id).then(r=>{if(!r.ok)throw Error();return r.json()})}catch{}
  const name=x?.name||local?.name||'Show Details';
  V.innerHTML='<h2>'+esc(name)+'</h2><div class="card">'+(x?.image?.medium?'<img class="poster" src="'+esc(x.image.medium)+'">':'')+'<div class="sub" style="margin-top:12px">'+(x?.summary?x.summary.replace(/<[^>]+>/g,''):esc(local?.network||''))+'</div></div><h3>Where to Watch</h3><div id="wtw" class="card"><div class="sub">Checking verified U.S. streaming availability…</div></div><button class="btn" style="margin-top:14px" onclick="go(\''+route+'\')">Back</button>';
  const W=$('#wtw'),d=await realProviders(name);
  if(!W)return;
  if(!d){W.innerHTML='<div class="empty">Where to Watch is unavailable right now.</div>';return}
  if(!d.found||!d.providers?.length){W.innerHTML='<div class="empty">No verified U.S. streaming options were found for this show.</div>';return}
  const labels={flatrate:'Stream',free:'Free',ads:'With Ads',rent:'Rent',buy:'Buy'};
  W.innerHTML='<div class="sub" style="margin-bottom:10px">Verified provider availability for the U.S.</div>'+d.providers.map(p=>'<div style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #e7edf5">'+(p.logo?'<img src="'+esc(p.logo)+'" alt="" style="width:38px;height:38px;border-radius:8px;object-fit:cover">':'')+'<div><b>'+esc(p.name)+'</b><div class="sub">'+esc(labels[p.type]||p.type)+'</div></div></div>').join('')+(d.link?'<a class="btn" style="display:inline-block;text-decoration:none;margin-top:12px" href="'+esc(d.link)+'" target="_blank" rel="noopener">View Watch Options</a>':'')
}
function more(){V.innerHTML='<h2>More</h2>'+[['catchup','Catch Up'],['night','Build My Night'],['subscriptions','Subscriptions'],['settings','Settings']].map(x=>'<button class="card" style="width:100%;text-align:left;font-weight:800" data-go="'+x[0]+'" onclick="go(\''+x[0]+'\')">'+x[1]+'</button>').join('')}
let catchupEpisodeCache=new Map();
async function catchup(){
 if(!(await hasPlan('plus'))){return lockedFeature('Catch Up','Calendar+ or higher')}
 V.innerHTML='<h2>Catch Up</h2><div class="sub" style="margin-bottom:16px">Your followed shows, organized by show and season. Open only the season you want.</div><div id="catchupList"><div class="empty">Loading episodes…</div></div>';
 const R=$('#catchupList');if(!shows.length){R.innerHTML='<div class="empty">Follow shows from Discover and they will appear here.</div>';return}
 const today=new Date();today.setHours(23,59,59,999);
 const results=await Promise.all(shows.map(async s=>{try{const eps=await fetch('https://api.tvmaze.com/shows/'+Number(s.id)+'/episodes').then(r=>{if(!r.ok)throw Error();return r.json()});return{show:s,eps:eps.filter(e=>e.airdate&&new Date(e.airdate+'T23:59:59')<=today)}}catch{return{show:s,eps:[],error:true}}}));
 catchupEpisodeCache=new Map(results.filter(r=>!r.error).map(r=>[Number(r.show.id),r.eps]));
 R.innerHTML=results.map(({show,eps,error})=>{if(error)return '<div class="card"><div class="title">'+esc(show.name)+'</div><div class="sub">Episode data unavailable right now.</div></div>';if(!eps.length)return '';
 const seasons={};eps.forEach(e=>(seasons[e.season??0]||(seasons[e.season??0]=[])).push(e));
 const total=eps.length,completed=eps.filter(e=>watched[String(e.id)]).length,remaining=total-completed;const status=remaining===0?'All caught up':completed===0?'Not started':remaining+' to watch';
 const seasonButtons=Object.keys(seasons).sort((a,b)=>Number(b)-Number(a)).map(sn=>{const a=seasons[sn],done=a.filter(e=>watched[String(e.id)]).length,left=a.length-done;return '<div data-catchup-season="'+Number(sn)+'" style="display:flex;align-items:center;gap:8px;padding:8px 0"><button style="flex:1;min-width:0;text-align:left;border:0;background:transparent;color:inherit;padding:0;cursor:pointer" onclick="openCatchupSeason('+Number(show.id)+','+Number(sn)+')"><span style="font-weight:650;font-size:14px">Season '+sn+'</span><span data-season-status style="font-size:12px;opacity:.65;margin-left:8px">'+(left===0?'✓ Watched':left+' to watch')+'</span></button><div data-season-actions style="display:flex;gap:5px;flex-shrink:0">'+(left>0?'<button class="btn" style="font-size:10px;padding:5px 7px" onclick="watchAllSeason('+Number(show.id)+','+Number(sn)+')">Watch All</button>':'')+(done>0?'<button class="btn" style="font-size:10px;padding:5px 7px;background:transparent;color:inherit;border:1px solid #ccd5df" onclick="unwatchAllSeason('+Number(show.id)+','+Number(sn)+')">Unwatch All</button>':'')+'</div></div>'}).join('');
 return '<section class="card" data-catchup-show="'+Number(show.id)+'" style="padding:14px"><div style="display:flex;align-items:center;gap:12px">'+(show.image?'<img class="poster" style="width:54px;height:78px" src="'+esc(show.image)+'">':'')+'<div style="min-width:0"><div class="title">'+esc(show.name)+'</div><div class="sub" data-watch-summary style="margin-top:4px">'+status+' · '+completed+' of '+total+' watched</div></div></div><div style="margin-top:10px">'+seasonButtons+'</div></section>'}).join('')||'<div class="empty">No aired episodes found.</div>';
}
async function openCatchupSeason(showId,season){const s=shows.find(x=>Number(x.id)===Number(showId));V.innerHTML='<h2>'+esc(s?.name||'Catch Up')+'</h2><button class="btn" onclick="catchup()">← All Seasons</button><div id="catchupSeason" style="margin-top:12px"><div class="empty">Loading Season '+season+'…</div></div>';const R=$('#catchupSeason');try{const eps=await fetch('https://api.tvmaze.com/shows/'+Number(showId)+'/episodes').then(r=>r.json());const a=eps.filter(e=>Number(e.season)===Number(season)&&e.airdate&&new Date(e.airdate+'T23:59:59')<=new Date()).sort((x,y)=>Number(x.number)-Number(y.number));R.innerHTML='<div class="card"><div class="title">Season '+season+'</div><div class="sub">'+a.filter(e=>watched[String(e.id)]).length+' of '+a.length+' watched</div>'+(a.some(e=>!watched[String(e.id)])?'<button class="btn" style="margin-top:12px" onclick="watchAllSeason('+Number(showId)+','+Number(season)+')">✓ Watch All</button>':'')+(a.some(e=>watched[String(e.id)])?'<button class="btn" style="margin-top:12px;margin-left:8px" onclick="unwatchAllSeason('+Number(showId)+','+Number(season)+')">↶ Unwatch All</button>':'')+'</div>'+a.map(e=>{const done=!!watched[String(e.id)];return '<div class="card"><div class="title">Episode '+(e.number??'—')+' • '+esc(e.name||'Episode')+'</div><div class="sub">'+esc(mdY(e.airdate))+(e.runtime?' • '+e.runtime+' min':'')+'</div><button class="btn" style="margin-top:10px;'+(done?'background:#19a974':'')+'" onclick="toggleWatchedSeason('+Number(e.id)+','+Number(showId)+','+Number(season)+')">'+(done?'✓ Watched':'Mark Watched')+'</button></div>'}).join('')}catch{R.innerHTML='<div class="empty">Could not load this season right now.</div>'}}
async function watchAllCatchup(){if(!shows.length)return;try{const results=await Promise.all(shows.map(async s=>{const r=await fetch('https://api.tvmaze.com/shows/'+Number(s.id)+'/episodes');if(!r.ok)throw Error('Episodes unavailable');return r.json()}));const now=new Date();const ids=[...new Set(results.flat().filter(e=>e.id&&e.airdate&&new Date(e.airdate+'T23:59:59')<=now&&!watched[String(e.id)]).map(e=>String(e.id)))];if(!ids.length){alert('All aired episodes are already marked Watched.');return}if(!confirm('Mark '+ids.length+' aired episodes across all followed shows as Watched? This will hide them from your calendar.'))return;ids.forEach(id=>watched[id]=true);save(K.watched,watched);catchup()}catch{alert('Could not load all episodes. No changes were made. Please try again.')}}
function updateCatchupShowInPlace(showId){const eps=catchupEpisodeCache.get(Number(showId));const card=document.querySelector('[data-catchup-show="'+Number(showId)+'"]');if(!eps||!card)return false;const total=eps.length,completed=eps.filter(e=>watched[String(e.id)]).length,remaining=total-completed;const summary=card.querySelector('[data-watch-summary]');if(summary)summary.textContent=(remaining===0?'All caught up':completed===0?'Not started':remaining+' to watch')+' · '+completed+' of '+total+' watched';card.querySelectorAll('[data-catchup-season]').forEach(row=>{const sn=Number(row.getAttribute('data-catchup-season'));const a=eps.filter(e=>Number(e.season??0)===sn),done=a.filter(e=>watched[String(e.id)]).length,left=a.length-done;const status=row.querySelector('[data-season-status]');if(status)status.textContent=left===0?'✓ Watched':left+' to watch';const actions=row.querySelector('[data-season-actions]');if(actions)actions.innerHTML=(left>0?'<button class="btn" style="font-size:10px;padding:5px 7px" onclick="watchAllSeason('+Number(showId)+','+sn+')">Watch All</button>':'')+(done>0?'<button class="btn" style="font-size:10px;padding:5px 7px;background:transparent;color:inherit;border:1px solid #ccd5df" onclick="unwatchAllSeason('+Number(showId)+','+sn+')">Unwatch All</button>':'')});return true}
async function refreshWatchedWithoutJump(showId,season){const inSeason=!!document.getElementById('catchupSeason');const pageY=window.scrollY,viewY=V.scrollTop;const scroller=document.scrollingElement,scrollY=scroller?scroller.scrollTop:pageY;if(inSeason)await openCatchupSeason(showId,season);else if(!updateCatchupShowInPlace(showId))await catchup();requestAnimationFrame(()=>{if(scroller)scroller.scrollTop=scrollY;window.scrollTo(0,pageY);V.scrollTop=viewY;requestAnimationFrame(()=>{if(scroller)scroller.scrollTop=scrollY;window.scrollTo(0,pageY);V.scrollTop=viewY})})}
async function setSeasonWatched(showId,season,mark){try{const show=Number(showId),sn=Number(season);let eps=catchupEpisodeCache.get(show);if(!eps){const response=await fetch('https://api.tvmaze.com/shows/'+show+'/episodes');if(!response.ok)throw Error('Episode list unavailable');const all=await response.json();const today=new Date();today.setHours(23,59,59,999);eps=all.filter(e=>e.airdate&&new Date(e.airdate+'T23:59:59')<=today)}const ids=eps.filter(e=>Number(e.season??0)===sn&&e.id&&Boolean(watched[String(e.id)])!==mark).map(e=>String(e.id));if(!ids.length){await refreshWatchedWithoutJump(show,sn);return}if(!confirm((mark?'Mark all '+ids.length+' remaining episodes':'Mark '+ids.length+' watched episodes')+' in Season '+sn+' as '+(mark?'Watched':'Unwatched')+'?'))return;ids.forEach(id=>{if(mark)watched[id]=true;else delete watched[id]});save(K.watched,watched);await refreshWatchedWithoutJump(show,sn)}catch(err){alert('Could not update this season. Please try again.')}}
async function watchAllSeason(showId,season){return setSeasonWatched(showId,season,true)}
async function unwatchAllSeason(showId,season){return setSeasonWatched(showId,season,false)}
function toggleWatchedSeason(id,showId,season){const k=String(id);if(watched[k])delete watched[k];else watched[k]=true;save(K.watched,watched);openCatchupSeason(showId,season)}
function toggleWatched(id){const k=String(id);if(watched[k])delete watched[k];else watched[k]=true;save(K.watched,watched);catchup()}
let nightLastPlan=[];
async function night(){if(!(await hasPlan('pro'))){return lockedFeature('Build My Night','Pro or Lifetime')}V.innerHTML='<h2>Build My Night</h2><div class="sub" style="margin-bottom:16px">Create a personalized lineup from your shows and movie watchlist.</div><div class="card"><div class="title">1. Time</div><select id="nightBudget" class="search"><option value="30">30 mins</option><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120" selected>2 hours</option><option value="180">3 hours</option><option value="240">4 hours</option></select></div><div class="card"><div class="title">2. What are you in the mood for?</div><select id="nightMood" class="search"><option value="any">Anything</option><option>Comedy</option><option>Drama</option><option>Action</option><option>Crime</option><option>Reality</option></select></div><div class="card"><div class="title">3. What should I use?</div><select id="nightSource" class="search"><option value="shows">My TV Shows</option><option value="favorites">Favorites First</option><option value="mix">TV Shows + Movie Watchlist</option></select></div><div class="card"><div class="title">4. Who is watching?</div><select id="nightGroup" class="search"><option>Just Me</option><option>Couple / Date Night</option><option>Family</option><option>Friends</option></select></div><div class="card"><div class="title">5. Plan style</div><select id="nightStyle" class="search"><option value="catchup">Catch Up</option><option value="favorites">Favorites First</option><option value="different">Something Different</option><option value="surprise">Surprise Me</option></select><button class="btn" style="width:100%;margin-top:14px" onclick="buildNight()">Build My Night</button></div><div id="nightPlan"></div>'}
async function buildNight(){const R=$('#nightPlan'),budget=Number($('#nightBudget')?.value||120),style=$('#nightStyle')?.value||'catchup';R.innerHTML='<div class="empty">Building your night…</div>';const today=new Date();today.setHours(23,59,59,999);let all=[];await Promise.all(shows.map(async s=>{try{const eps=await fetch('https://api.tvmaze.com/shows/'+Number(s.id)+'/episodes').then(r=>r.json());eps.forEach(e=>{if(e.airdate&&new Date(e.airdate+'T23:59:59')<=today&&!watched[String(e.id)])all.push({show:s,e,mins:Number(e.runtime||s.runtime||45),fav:!!favorites[String(s.id)]})})}catch{}}));if(style==='favorites')all.sort((a,b)=>Number(b.fav)-Number(a.fav));else if(style==='different')all.sort((a,b)=>String(a.show.name).localeCompare(String(b.show.name)));else if(style==='surprise')all.sort(()=>Math.random()-.5);else all.sort((a,b)=>String(b.e.airdate).localeCompare(String(a.e.airdate)));let left=budget,plan=[];for(const x of all){if(x.mins<=left){plan.push(x);left-=x.mins}}nightLastPlan=plan;if(!plan.length){R.innerHTML='<div class="empty">No unwatched episodes fit this plan. Try more time or another style.</div>';return}R.innerHTML='<div class="card"><div class="title">Your '+budget+'-Minute Night Is Ready</div><div class="sub">'+(budget-left)+' minutes planned • '+left+' minutes free</div><button class="btn" style="margin-top:10px" onclick="buildNight()">↻ Shuffle / Rebuild</button></div>'+plan.map((x,i)=>'<div class="card"><div class="sub">#'+(i+1)+' • '+x.mins+' min</div><div class="title">'+esc(x.show.name)+'</div><div>'+esc('S'+String(x.e.season??0).padStart(2,'0')+'E'+String(x.e.number??0).padStart(2,'0')+' • '+(x.e.name||'Episode'))+'</div><button class="btn" style="margin-top:10px" onclick="nightWatched('+Number(x.e.id)+')">✓ Mark Watched</button></div>').join('')}
function nightWatched(id){watched[String(id)]=true;save(K.watched,watched);buildNight()}
function notificationPrefs(){return load('mytv-notification-prefs',{showToday:true,movieToday:true,showSoon:false,dateChanges:false,newSeason:false,appUpdates:false})}
function setNotificationPref(k,v){const p=notificationPrefs();p[k]=!!v;save('mytv-notification-prefs',p);syncNotificationPrefs()}
async function settings(){
 const plan=await getCurrentPlan(),level=PLAN_LEVELS[plan]||0,p=notificationPrefs();
 const row=(k,label,desc,need=0,badge='Free')=>{const locked=level<need;return '<label class="card" style="display:flex;align-items:center;justify-content:space-between;gap:14px;'+(locked?'opacity:.5;':'')+'"><div><div class="title">'+label+(locked?' <span class="sub">• '+badge+'</span>':'')+'</div><div class="sub">'+desc+'</div></div><input type="checkbox" '+(!locked&&p[k]?'checked':'')+' '+(locked?'disabled':'onchange="setNotificationPref(\''+k+'\',this.checked)"')+' style="width:22px;height:22px;flex:0 0 auto"></label>'};
 V.innerHTML='<h2>Settings</h2><div class="card"><div class="title">Push Notifications</div><div class="sub">Enable notifications, then choose the reminders included with your plan.</div><button type="button" id="push-toggle" class="btn" data-push="on" style="margin-top:12px">Enable Push Notifications</button><div id="push-msg" class="sub" style="margin-top:10px"></div></div><div class="title" style="margin:18px 0 10px">Notification Preferences</div>'+row('showToday','📺 Show Airing Today','Remind me when a followed show has a new episode today.',0,'Free')+row('movieToday','🎬 Movie Release Today','Remind me when a movie in my Watchlist releases today.',1,'Calendar+')+row('dateChanges','📅 Release Date Changes','Tell me when a followed show or movie release date changes.',1,'Calendar+')+row('showSoon','⏰ Show Starting Soon','Remind me shortly before a followed show starts.',2,'Pro')+row('newSeason','✨ New Season / Premiere','Tell me when a followed show begins a new season.',2,'Pro')+row('appUpdates','🔔 My TV Calendar Updates','Important app and account announcements.',0,'Free')+'<div class="card">My TV Calendar V6.4.78</div>';
 renderPushButton();
}
const BILLING_PORTAL='https://billing.stripe.com/p/login/8x24gycwP7vC7kT1Aeco000';
const PAYMENT_LINKS={plus:'https://buy.stripe.com/dRm7sKfJ17vC9t17YCco003',pro:'https://buy.stripe.com/5kQ8wO1Sb8zG8oXfr4co004',lifetime:'https://buy.stripe.com/8x2fZgeEX6rygVt5Quco005'};
const PLAN_LABELS={free:'Free',plus:'Calendar+',pro:'Pro',lifetime:'Lifetime'};
const PLAN_LEVELS={free:0,plus:1,pro:2,lifetime:3};
let PLAN_CACHE={plan:'free',at:0};
async function getSessionUser(){if(!SB)return null;try{const {data}=await SB.auth.getSession();return data?.session?.user||null}catch{return null}}
async function getCurrentPlan(force=false){
 if(!force&&Date.now()-PLAN_CACHE.at<15000)return PLAN_CACHE.plan;
 const user=await getSessionUser();if(!user){PLAN_CACHE={plan:'free',at:Date.now()};return'free'}
 try{
  const {data,error}=await SB.from('user_entitlements').select('plan,status,lifetime,current_period_end,updated_at').order('updated_at',{ascending:false});
  if(error)throw error;
  const good=(data||[]).filter(x=>x.lifetime||['active','trialing'].includes(String(x.status||'')));
  const plan=good.reduce((best,x)=>(PLAN_LEVELS[x.plan]||0)>(PLAN_LEVELS[best]||0)?x.plan:best,'free');
  PLAN_CACHE={plan,at:Date.now()};return plan;
 }catch{PLAN_CACHE={plan:'free',at:Date.now()};return'free'}
}
async function hasPlan(required){const user=await getSessionUser();if(!user){PLAN_CACHE={plan:'free',at:Date.now()};return false}const p=await getCurrentPlan(true);return (PLAN_LEVELS[p]||0)>=(PLAN_LEVELS[required]||0)}
function lockedFeature(name,need){V.innerHTML='<h2>'+esc(name)+'</h2><div class="card"><div class="title">Premium Feature</div><div class="sub">'+esc(name)+' is available with '+esc(need)+'.</div><button class="btn" style="width:100%;margin-top:14px" onclick="go(\'subscriptions\')">View Subscriptions</button></div>'}
