 '<div class="card"><div class="title">My TV Calendar Pro</div><h2 style="margin:6px 0">$4.99 <span class="sub">/ month</span></h2><div class="sub">Everything in Calendar+ • Build My Night • Show Starting Soon alerts • New Season / Premiere alerts • Advanced planning features</div><button class="btn" '+(owns('pro')?'disabled style="width:100%;margin-top:14px;opacity:.65"':(user?enabledStyle:disabled))+' onclick="startCheckout(\'pro\')">'+(owns('pro')?'Included in '+esc(PLAN_LABELS[plan]):'Go Pro')+'</button></div>'+
 '<div class="card"><div class="title">My TV Calendar Lifetime</div><h2 style="margin:6px 0">$29.99 <span class="sub">one time</span></h2><div class="sub">Pay once and unlock all current premium features and all notification types with no monthly subscription.</div><button class="btn" '+(plan==='lifetime'?'disabled style="width:100%;margin-top:14px;opacity:.65"':(user?enabledStyle:disabled))+' onclick="startCheckout(\'lifetime\')">'+(plan==='lifetime'?'Current Plan':'Get Lifetime Access')+'</button></div>'+
 '<div class="sub" style="text-align:center;margin:14px">Secure checkout powered by Stripe.</div>';
 if(paidSuccess&&history.replaceState){const u=new URL(location.href);u.searchParams.delete('payment');history.replaceState({},'',u.toString())}
