function showAccountCreatedModal(email,needsConfirm=true,existing=false){
 const old=document.getElementById('accountCreatedModal');if(old)old.remove();
 const d=document.createElement('div');d.id='accountCreatedModal';d.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.72);display:flex;align-items:center;justify-content:center;padding:22px';
 const msg=!needsConfirm?'Your account is ready and you are signed in.':existing?'This email already has an account. If you still need to confirm it, tap Resend Confirmation Email below.':'We sent a confirmation email to <b>'+esc(email)+'</b>. Open the email and tap the confirmation link before signing in.';
 const resend=needsConfirm?'<button class="btn" style="width:100%;margin-top:10px" onclick="resendConfirmation(\''+String(email).replace(/'/g,"\\'")+'\')">Resend Confirmation Email</button>':'';
 d.innerHTML='<div class="card" style="width:min(420px,100%);text-align:center;padding:24px"><div style="font-size:42px;margin-bottom:8px">✓</div><div class="title" style="font-size:22px">'+(existing?'Account Already Exists':'Account Created')+'</div><div id="accountConfirmMsg" class="sub" style="margin-top:10px">'+msg+'</div>'+resend+'<button class="btn" style="width:100%;margin-top:10px" onclick="closeAccountCreatedModal()">OK</button></div>';
 document.body.appendChild(d);
}
async function resendConfirmation(email){
 const m=$('#accountConfirmMsg');if(m)m.textContent='Sending confirmation email…';
 try{const {error}=await SB.auth.resend({type:'signup',email,options:{emailRedirectTo:'https://animaxionx.github.io/mytv-calendar/?route=subscriptions'}});if(error)throw error;if(m)m.textContent='Confirmation email sent. Check your inbox and spam folder.'}
 catch(err){if(m)m.textContent='Could not resend confirmation email. '+(err?.message||'Please try again.')}
}
function closeAccountCreatedModal(){document.getElementById('accountCreatedModal')?.remove();subscriptions()}
function togglePasswordVisibility(){const p=$('#subPass'),b=$('#pwToggle');if(!p||!b)return;const hidden=p.getAttribute('data-password-state')!=='visible';if(hidden){p.type='text';p.setAttribute('data-password-state','visible');b.textContent='◉';b.title='Hide password';b.setAttribute('aria-label','Hide password')}else{p.type='password';p.setAttribute('data-password-state','hidden');b.textContent='👁';b.title='Show password';b.setAttribute('aria-label','Show password')}}
async function signInAccount(){
 const e=$('#subEmail')?.value.trim(),p=$('#subPass')?.value||'',m=$('#subAuthMsg'),b=document.querySelector('button[onclick="signInAccount()"]');
 if(!e||!p){if(m)m.textContent='Enter your email and password.';return}
 if(!SB){if(m)m.textContent='Login service did not load. Refresh the app and try again.';return}
 if(m)m.textContent='Signing in…';if(b){b.disabled=true;b.textContent='Signing In…'}
 try{
  const {data,error}=await SB.auth.signInWithPassword({email:e,password:p});
  if(error){if(m)m.textContent=error.message;return}
  if(!data?.session){if(m)m.textContent='Sign in was not completed. Check your email confirmation and try again.';return}
  PLAN_CACHE.at=0;if(m)m.textContent='Signed in successfully.';await getCurrentPlan(true);await reconcileNotificationRegistration();await go('home');
 }catch(err){if(m)m.textContent='Could not sign in. '+(err?.message||'Please try again.')}
 finally{if(b){b.disabled=false;b.textContent='Sign In'}}
}
async function createAccount(){
 const e=$('#subEmail')?.value.trim(),p=$('#subPass')?.value||'',m=$('#subAuthMsg'),b=document.querySelector('button[onclick="createAccount()"]');
 if(!e||p.length<6){if(m)m.textContent='Enter a valid email and a password with at least 6 characters.';return}
 if(!SB){if(m)m.textContent='Account service did not load. Refresh the app and try again.';return}
 if(m)m.textContent='Creating account…';if(b){b.disabled=true;b.textContent='Creating…'}
 try{
  const {data,error}=await SB.auth.signUp({email:e,password:p,options:{emailRedirectTo:'https://animaxionx.github.io/mytv-calendar/?route=subscriptions'}});
  if(error){if(m)m.textContent=error.message;return}
  if(data?.session){PLAN_CACHE.at=0;showAccountCreatedModal(e,false,false)}
  else {
   const created=String(data?.user?.identities?.length||0)!=='0';
   showAccountCreatedModal(e,true,!created);
  }
 }catch(err){if(m)m.textContent='Could not create account. '+(err?.message||'Please try again.')}
 finally{if(b){b.disabled=false;b.textContent='Create Account'}}
}
function passwordRecoveryScreen(){
 V.innerHTML='<h2>Reset Password</h2><div class="card"><div class="title">Create a new password</div><div class="sub">Enter your new password below.</div><input id="recoveryPass" class="search" type="password" placeholder="New Password" autocomplete="new-password" style="margin-top:12px"><input id="recoveryPass2" class="search" type="password" placeholder="Confirm New Password" autocomplete="new-password" style="margin-top:8px"><button id="recoveryBtn" class="btn" style="width:100%;margin-top:12px" onclick="completePasswordRecovery()">Update Password</button><div id="recoveryMsg" class="sub" style="margin-top:10px"></div></div>';
}
async function completePasswordRecovery(){
 const p=$('#recoveryPass')?.value||'',p2=$('#recoveryPass2')?.value||'',m=$('#recoveryMsg'),b=$('#recoveryBtn');
 if(p.length<6){if(m)m.textContent='Password must be at least 6 characters.';return}
 if(p!==p2){if(m)m.textContent='Passwords do not match.';return}
 if(m)m.textContent='Updating password…';if(b)b.disabled=true;
 try{const {error}=await SB.auth.updateUser({password:p});if(error)throw error;if(m)m.textContent='Password updated successfully. Taking you to your account…';PLAN_CACHE.at=0;setTimeout(()=>{go('subscriptions')},900)}
 catch(err){if(m)m.textContent='Could not update password. '+(err?.message||'Please request a new reset link and try again.')}
 finally{if(b)b.disabled=false}
}
async function signOutAccount(){if(SB)await SB.auth.signOut();PLAN_CACHE={plan:'free',at:Date.now()};await go('subscriptions')}
async function startCheckout(plan){
 const user=await getSessionUser();if(!user){alert('Sign in first so your purchase can activate automatically.');return}
 const base=PAYMENT_LINKS[plan];if(!base)return;
 const u=new URL(base);u.searchParams.set('locked_prefilled_email',user.email||'');u.searchParams.set('client_reference_id',user.id);location.href=u.toString();
}
const qs=new URLSearchParams(location.search);
let recoveryMode=false;
if(SB)SB.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){recoveryMode=true;passwordRecoveryScreen()}});
(async()=>{if(SB){try{const {data}=await SB.auth.getSession();const h=new URLSearchParams(location.hash.replace(/^#/,''));if((h.get('type')==='recovery'||qs.get('type')==='recovery')&&data?.session){recoveryMode=true;passwordRecoveryScreen();return}}catch{}}
if(!recoveryMode){await reconcileNotificationRegistration();await refreshFollowedSchedules();if(qs.get('payment')==='success'||qs.get('route')==='subscriptions')await go('subscriptions');else await go('home')}})();